def solve(grid):
    from collections import Counter, deque

    h = len(grid)
    w = len(grid[0]) if h else 0

    # Count colors
    cnt = Counter()
    for row in grid:
        for v in row:
            if v != 0:
                cnt[v] += 1

    # Identify marker color 5 and the unique special color
    marker_color = 5
    special_color = None
    for c, n in cnt.items():
        if c != marker_color and n == 1:
            special_color = c
            break

    # Main repeated object color
    main_color = None
    best = -1
    for c, n in cnt.items():
        if c not in (marker_color, special_color) and n > best:
            best = n
            main_color = c

    # Copy and clear markers/special
    out = [row[:] for row in grid]
    marker_cells = []
    special_cell = None
    for r in range(h):
        for c in range(w):
            if out[r][c] == marker_color:
                marker_cells.append((r, c))
                out[r][c] = 0
            elif special_color is not None and out[r][c] == special_color:
                special_cell = (r, c)
                out[r][c] = 0

    if main_color is None or special_color is None or special_cell is None or len(marker_cells) < 2:
        return out

    # Connected components of the main color (4-connected)
    vis = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if out[r][c] == main_color and not vis[r][c]:
                q = deque([(r, c)])
                vis[r][c] = True
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and not vis[nx][ny] and out[nx][ny] == main_color:
                            vis[nx][ny] = True
                            q.append((nx, ny))
                comps.append(cells)

    # Direction of the marker diagonal
    marker_cells.sort()
    step_r = special_cell[0] - marker_cells[-1][0]
    step_c = special_cell[1] - marker_cells[-1][1]
    if step_r == 0:
        step_r = 1 if special_cell[0] > marker_cells[0][0] else -1
    else:
        step_r = 1 if step_r > 0 else -1
    if step_c == 0:
        step_c = 1 if special_cell[1] > marker_cells[0][1] else -1
    else:
        step_c = 1 if step_c > 0 else -1

