    norm_shapes = []
    for cells in comps:
        minr = min(r for r, c in cells)
        minc = min(c for r, c in cells)
        norm_shapes.append(tuple(sorted((r - minr, c - minc) for r, c in cells))))
    identical = len(set(norm_shapes)) == 1

    target_cell = None

    if identical:
        # Choose extreme opposite to diagonal direction
        def key_for_comp(cells):
            minr = min(r for r, c in cells)
            maxr = max(r for r, c in cells)
            minc = min(c for r, c in cells)
            maxc = max(c for r, c in cells)
            if (step_r, step_c) == (1, 1):      # choose top-leftmost
