            (cr - step_r, cc),
            (cr, cc - step_c),
            (min(r for r, c in comp) - (1 if step_r == 1 else 0),
             min(c for r, c in comp) - (1 if step_c == 1 else 0)),
        ]
        for r, c in candidates:
            if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
                target_cell = (r, c)
                break
    else:
        # Fallback heuristic for non-identical examples:
        # choose largest component, tie-broken by direction extreme
        def key_for_comp(cells):
            minr = min(r for r, c in cells)
            maxr = max(r for r, c in cells)
            minc = min(c for r, c in cells)
