            candidates = [(minr, minc - 1), (minr - 1, minc - 1), (minr - 1, minc)]
        elif (step_r, step_c) == (-1, -1):
            candidates = [(minr - 1, minc - 1), (minr, minc - 1), (minr - 1, minc)]
        else:
            candidates = [(maxr + 1, minc), (maxr + 1, minc - 1), (maxr, minc - 1)]

        for r, c in candidates:
